             key=lambda v: sum(row.count(v) for row in grid))
    counts = {}
    for row in grid:
        prev = bg
        for v in row:
            if v != bg and v != prev:
                counts[v] = counts.get(v, 0) + 1
            prev = v

    out = [[bg] * 3 for _ in range(2)]
    cells = []
    for color in (3, 2):
        cells.extend([color] * counts.get(color, 0))
    cells = (cells + [bg] * 6)[:6]
    for i, color in enumerate(cells):
        out[i // 3][i % 3] = color
    return out
