def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {2: 0, 3: 0}

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in counts or (r, c) in seen:
                continue
            counts[color] += 1
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
